import re, os, subprocess
S='/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/10_cluster/C3/public/snapshots/s03'
out=subprocess.run(['grep','-rn','.changelink','drivers','net','--include=*.c'],cwd=S,capture_output=True,text=True).stdout
targets=[]
for line in out.splitlines():
    parts=line.split(':',2)
    if len(parts)<3: continue
    path,ln,txt=parts
    if 'NULL' in txt: continue
    m=re.search(r'=\s*(\w+)\s*,',txt)
    if m: targets.append((path,int(ln),m.group(1)))

def func_body(src, name):
    pat=re.compile(r'^[^\n]*?\b'+re.escape(name)+r'\s*\(', re.M)
    m=pat.search(src)
    if not m: return None
    start=src.rfind('\n',0,m.start())+1
    idx=src.find('{', m.end())
    if idx<0: return None
    depth=0; i=idx
    while i<len(src):
        c=src[i]
        if c=='{': depth+=1
        elif c=='}':
            depth-=1
            if depth==0:
                return (start, src.count('\n',0,i)+1, src[start:i+1])
        i+=1
    return None

use_re=re.compile(r'(?:nla_data|nla_get_\w+|nla_len|nla_nest_start|memcpy|memcmp|nla_strlcpy|nla_strdup)\s*\(\s*(?:data|tb|info->attrs)\[([A-Z][A-Z0-9_]+)\]')
guard_re=re.compile(r'\b(?:data|tb)\[([A-Z][A-Z0-9_]+)\]\s*\)|!\s*(?:data|tb)\[([A-Z][A-Z0-9_]+)\]|\b(?:data|tb)\[([A-Z][A-Z0-9_]+)\]\s*(?:\?|&&|\|\||==|,)

for path,ln,name in targets:
    full=os.path.join(S,path)
    src=open(full,errors='ignore').read()
    r=func_body(src,name)
    if not r:
        print(f"## {path}:{ln} {name}: EXTRACT FAIL"); continue
    start,end,body=r
    lines=body.splitlines()
    # per-line analysis: a use on a line is "guarded" if the attribute appears in a condition context anywhere before it within the function
    guarded=set()
    problems=[]
    for i,l in enumerate(lines):
        # guards: 'if (...X)' or '!X' or 'X ?' or 'X &&'
        for m in re.finditer(r'!\s*(?:data|tb)\[([A-Z][A-Z0-9_]+)\]', l):
            guarded.add(m.group(1))
        for m in re.finditer(r'(?:data|tb)\[([A-Z][A-Z0-9_]+)\]\s*(?:\?|&&|\|\|)', l):
            guarded.add(m.group(1))
        if re.match(r'\s*(if|switch|while)\s*\(', l):
            for m in re.finditer(r'(?:data|tb)\[([A-Z][A-Z0-9_]+)\]', l):
                guarded.add(m.group(1))
        # uses
        for m in use_re.finditer(l):
            a=m.group(1)
            if a not in guarded:
                problems.append((start+i, a, l.strip()))
        # direct pointer use like data[X]-> ... or nla_nest... also tb[X] passed to function (other than the guard macros)
        for m in re.finditer(r'(?:data|tb)\[([A-Z][A-Z0-9_]+)\]\s*->', l):
            a=m.group(1)
            if a not in guarded:
                problems.append((start+i, a, l.strip()))
    if problems:
        print(f"## {path} {name} (lines {start}-{end}):")
        for l,a,t in problems:
            print(f"   L{l}: [{a}] {t[:120]}")
PYEOF
